import{_ as n,o as r,c as t,ag as s}from"./chunks/framework.D5hoimZQ.js";const h=JSON.parse('{"title":"🔬 科学日报 | 2026年10月29日 · 深度扩展","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/science-daily/2026-10-29.md","filePath":"science-log/src/science-daily/2026-10-29.md"}'),g={name:"science-log/src/science-daily/2026-10-29.md"};function e(a,o,i,c,d,p){return r(),t("div",null,[...o[0]||(o[0]=[s('<h1 id="🔬-科学日报-2026年10月29日-·-深度扩展" tabindex="-1">🔬 科学日报 | 2026年10月29日 · 深度扩展 <a class="header-anchor" href="#🔬-科学日报-2026年10月29日-·-深度扩展" aria-label="Permalink to &quot;🔬 科学日报 | 2026年10月29日 · 深度扩展&quot;">​</a></h1><blockquote><p>来源：科学快报 第48期（共 10 条：科学前沿 5 + AI前沿 5） 分析日期：2026-10-29 版本：扩展版（10 条深度 + 交叉关联）</p></blockquote><hr><h2 id="🔬-一、科学前沿" tabindex="-1">🔬 一、科学前沿 <a class="header-anchor" href="#🔬-一、科学前沿" aria-label="Permalink to &quot;🔬 一、科学前沿&quot;">​</a></h2><h3 id="_1-首次合成「五元—七元环」碳纳米带-本征金属、近弹道输运" tabindex="-1">1. 首次合成「五元—七元环」碳纳米带：本征金属、近弹道输运 <a class="header-anchor" href="#_1-首次合成「五元—七元环」碳纳米带-本征金属、近弹道输运" aria-label="Permalink to &quot;1. 首次合成「五元—七元环」碳纳米带：本征金属、近弹道输运&quot;">​</a></h3><p><strong>原文</strong>：金属性碳基纳米带是原子级精确的一维导体，理想情况下电导可接近金属碳纳米管（量子极限）。此前金属性石墨烯纳米带靠能带工程（如零模超晶格）实现，但完全非苯环（non-benzenoid）碳同素异形体的原子级精确金属带——如理论预言的碳戊搭烯（carbon pentaheptite）——一直未被做出来。作者用层级式表面合成：先把预合成的聚环辛二烯链转化为排列整齐的聚戊搭烯链，再把这些链侧向融合成平面碳戊搭烯纳米带（CPHN）。两种窄带共用同一基底结构（中央一条七元环链，两侧是同向或异向取向的聚戊搭烯链）：CPHN 1 是本征金属，CPHN 2 是窄带隙半导体。CPHN 1 呈现接近一个电导量子的近弹道电导，可与金属碳纳米管相比。</p><p><strong>深度扩展</strong>：</p><p>金属性碳纳米带一直是「碳基电子学」的圣杯——理论上，其电导可像金属碳纳米管一样逼近一个电导量子 G₀ = 2e²/h。问题在于，已有的金属石墨烯纳米带多靠「能带工程」（外加电场、零模超晶格）而非材料本身的本征金属性。这篇发表于《Nature》（2026 年 10 月 28 日，第 658 卷 8138 期，1176–1182 页）的工作，由 Jianmin Huang、Qitang Fan、Jie Meng、Jia Liu、Jie Cui、Jianing Wang 等完成，用<strong>层级式表面合成（hierarchical on-surface synthesis）<strong>首次把理论预言的</strong>碳戊搭烯（carbon pentaheptite）</strong>——一种完全由五元环与七元环拼接、**不含任何苯环（non-benzenoid）**的碳同素异形体——做成了原子级精确的纳米带（CPHN）。</p><p>方法分两步：① 先把预合成的<strong>聚环辛二烯链</strong>在金属表面转化为排列整齐的<strong>聚戊搭烯链</strong>；② 再让这些链<strong>侧向融合</strong>成平面纳米带。关键数字：两种窄带共用同一基底（中央一条七元环链 + 两侧聚戊搭烯链，取向不同），其中 <strong>CPHN 1 是本征金属</strong>，室温电导接近<strong>一个电导量子</strong>、呈近弹道输运；<strong>CPHN 2 则是窄带隙半导体</strong>。为什么重要：这是「平面碳金属」的第一例，为「碳量子线」——可规模化、可图案化的全碳互连——提供了真实材料基础。</p><p><strong>跨主题关联</strong>：属于 <code>topics/materials/index.md</code>（碳基材料谱系）与 <code>topics/physics/index.md</code>（低维输运）的交汇；作为第48期简讯收录于 <code>topics/science-news/index.md</code>。</p><hr><h3 id="_2-石墨烯的「子周期录像」-直接拍到朗道–齐纳–马约拉纳隧穿" tabindex="-1">2. 石墨烯的「子周期录像」：直接拍到朗道–齐纳–马约拉纳隧穿 <a class="header-anchor" href="#_2-石墨烯的「子周期录像」-直接拍到朗道–齐纳–马约拉纳隧穿" aria-label="Permalink to &quot;2. 石墨烯的「子周期录像」：直接拍到朗道–齐纳–马约拉纳隧穿&quot;">​</a></h3><p><strong>原文</strong>：强光场能全光地裁剪电子的相干轨迹、改写能带乃至塑造物态，但要看懂机制，需要在能带里直接可视化光波驱动的电子运动。此前光电子动量显微只能拍多周期平均的激发电子，子周期能带录像又限于小动量。作者提出阿秒精度、覆盖整个第一布里渊区的子周期能带录像，可视化一种最基础却难捉摸的强场过程——非绝热 Landau–Zener–Majorana（LZM）隧穿：强场在石墨烯类狄拉克能带内的加速与周期性 LZ 带间隧穿相互交织，表现为布里渊区边缘载流子分布的相干子周期位移与畸变。</p><p><strong>深度扩展</strong>：</p><p>强激光场能在飞秒—阿秒尺度上改写电子的相干轨迹、甚至重塑物态，但「看见」电子在能带里被光驱动，一直是实验难题：光电子动量显微只能给出多周期平均图像，而子周期录像又受限于小动量区。这项工作（《Nature》2026 年 10 月 28 日，第 659 卷 8139 期，63–68 页；作者 V. Eggers、G. Inzani、M. Meierhofer、L. Münster、J. Helml、R. Wallauer 等）提出了一种<strong>覆盖整个第一布里渊区、阿秒精度</strong>的「子周期能带录像」。</p><p>它直接可视化了一类最基础却难捉摸的强场过程——<strong>非绝热 Landau–Zener–Majorana（LZM）隧穿</strong>：强场在石墨烯类狄拉克能带内<strong>加速</strong>电子，与<strong>周期性 LZ 带间隧穿</strong>相互交织，表现为布里渊区边缘载流子分布的<strong>相干子周期位移与畸变</strong>。关键突破：这种极端<strong>非热（non-thermal）分布</strong>能把相互竞争的散射过程<strong>分离开</strong>，使作者得以定量评估各散射通道对相干电子控制的影响。为什么重要：它把「强场操控量子材料」从黑箱变成全景显微镜下的动力学问题——为光场驱动的量子态裁剪提供了微观依据。</p><p><strong>跨主题关联</strong>：与 <code>topics/quantum-physics/index.md</code>、<code>topics/physics/index.md</code> 中强场物理/能带动力学笔记勾连——「外场=坐标变换、内禀能带=不变量」的结构与 <code>topics/cross-domain-synthesis-2026-q3.md</code> 的「代码-状态分离」同构。</p><hr><h3 id="_3-硅酮「回到单体」-脱氧氯化把惰性硅氧链直接拆回二氯硅烷" tabindex="-1">3. 硅酮「回到单体」：脱氧氯化把惰性硅氧链直接拆回二氯硅烷 <a class="header-anchor" href="#_3-硅酮「回到单体」-脱氧氯化把惰性硅氧链直接拆回二氯硅烷" aria-label="Permalink to &quot;3. 硅酮「回到单体」：脱氧氯化把惰性硅氧链直接拆回二氯硅烷&quot;">​</a></h3><p><strong>原文</strong>：硅酮因优异的热稳定性和化学惰性被广泛用于工业、医疗与消费品——也正因此，它的化学回收与高值化极其困难。当前的废硅酮处理主要是填埋、焚烧、机械回收、或回环状硅氧烷。作者提出一种硅鎓离子（silylium-ion）引发的解聚策略：用光气的更高级取代物、乃至光气本身作为脱氧氯化试剂，在温和条件下直接切断 Si–O–Si 键，重新生成工业上相关的二氯硅烷单体（闭环式「回料」回收）。</p><p><strong>深度扩展</strong>：</p><p>硅酮（聚硅氧烷）因优异的热稳定性与化学惰性被广泛用于工业、医疗与消费品，但也正因此，其化学回收与高值化极其困难：目前的废硅酮处理主要是<strong>填埋、焚烧、机械回收，或把长链打回环状硅氧烷</strong>，都难算真正的高值闭环。这项发表于《Nature》（2026 年 10 月 28 日）的工作，由 Biping Xu、Tobias Randt、Xiaojie Liu、Zheng-Wang Qu、Stefan Grimme、Hendrik F. T. Klare 等完成（作者组合指向德国波恩一脉的<strong>硅鎓离子化学</strong>传统，Grimme 以 DFT 方法著称），提出了一种<strong>硅鎓离子（silylium-ion）引发</strong>的解聚策略。</p><p>方法：用<strong>光气的更高级取代物、乃至光气本身</strong>作为<strong>脱氧氯化试剂</strong>，在<strong>温和条件</strong>下直接<strong>切断 Si–O–Si 键</strong>，重新生成工业上相关的<strong>二氯硅烷单体</strong>（即「回到单体」闭环回收）。关键点：该法<strong>底物普适性广</strong>，适用线性与环状硅氧烷，包括<strong>商用硅油与弹性体</strong>。机理 + 计算表明，光气并非只当氯源——在<strong>硅鎓离子路易斯酸活化</strong>下，它<strong>原位生成氯羰基阳离子</strong>作为真正的活性切割剂。为什么重要：它为化学惰性的硅氧烷材料提供了一条<strong>可持续循环回收</strong>的新路径——把「难降解」从缺点转为可控的定向断键。</p><p><strong>跨主题关联</strong>：与 <code>topics/materials/index.md</code> 的材料回收/循环经济条目关联；其「用强亲电试剂精确切断惰性键」的逻辑与 <code>topics/cross-domain-synthesis-2026-q3.md</code> 的「约束-涌现」模式呼应。</p><hr><h3 id="_4-心脏的「乳酸捷径」-mct1-把乳酸直接搬进线粒体供能" tabindex="-1">4. 心脏的「乳酸捷径」：MCT1 把乳酸直接搬进线粒体供能 <a class="header-anchor" href="#_4-心脏的「乳酸捷径」-mct1-把乳酸直接搬进线粒体供能" aria-label="Permalink to &quot;4. 心脏的「乳酸捷径」：MCT1 把乳酸直接搬进线粒体供能&quot;">​</a></h3><p><strong>原文</strong>：心脏能灵活氧化葡萄糖、乳酸等多种燃料以应对饮食、运动与损伤应激。传统观点认为糖类氧化都要先走胞质生成丙酮酸、再由线粒体丙酮酸载体（MPC）进入三羧酸（TCA）循环。作者发现，即使遗传敲除 MPC，小鼠心肌仍能氧化葡萄糖来源的碳；这条备用通路依赖单羧酸转运体 MCT1（Slc16a1）。进一步发现，通常定位于质膜的 MCT1 也存在于小鼠与人心肌细胞的线粒体内膜：它与基质中的 LDHB 搭档，在线粒体内把乳酸转成丙酮酸与 NADH，直接给电子传递链供料。</p><p><strong>深度扩展</strong>：</p><p>心脏能灵活氧化葡萄糖、乳酸、脂肪酸等多种燃料以应对饮食、运动与应激。传统教科书认为：糖类氧化都要先在胞质生成<strong>丙酮酸</strong>，再由**线粒体丙酮酸载体（MPC）**运入基质、进入三羧酸（TCA）循环。这项发表于《Nature》（2026 年 10 月 28 日）的工作，由 Ahmad A. Cluntun、Joseph R. Visker、Jesse N. Velasco-Silva、James Carrington、Luis Cedeño-Rosario、Giulia C. Napoli 等完成，颠覆了这一单通道假设。</p><p>关键发现：即使<strong>遗传敲除 MPC</strong>，小鼠心肌仍能氧化<strong>葡萄糖来源的碳</strong>——说明存在一条备用通路，且它<strong>依赖单羧酸转运体 MCT1（Slc16a1）</strong>。进一步，作者发现通常被认为定位于<strong>质膜</strong>的 MCT1，也存在于<strong>小鼠与人心肌细胞的线粒体内膜</strong>：它与基质中的 <strong>LDHB（乳酸脱氢酶 B）<strong>搭档，在</strong>线粒体内部</strong>把<strong>乳酸转成丙酮酸与 NADH</strong>，<strong>直接给电子传递链供料</strong>。关键数字/效应：缺失 MCT1 会损害乳酸氧化、<strong>破坏代谢灵活性</strong>，并在<strong>神经内分泌轴过度激活或缺血—再灌注损伤后加速心衰、增加死亡率</strong>。为什么重要：存在一条<strong>平行于丙酮酸的「乳酸通道」</strong>——糖代谢的瓶颈可能不在丙酮酸，而在一条被长期忽视的乳酸入线粒体通路。</p><p><strong>跨主题关联</strong>：与 <code>topics/biomedicine/index.md</code> 的能量代谢/心血管条目关联；「冗余通路保证鲁棒性、单点缺失才暴露脆弱性」与 <code>topics/cross-domain-synthesis-2026-q3.md</code> 的「约束-涌现」同构。</p><hr><h3 id="_5-出生前后-大脑「清算」数十亿基因组异常的神经元" tabindex="-1">5. 出生前后，大脑「清算」数十亿基因组异常的神经元 <a class="header-anchor" href="#_5-出生前后-大脑「清算」数十亿基因组异常的神经元" aria-label="Permalink to &quot;5. 出生前后，大脑「清算」数十亿基因组异常的神经元&quot;">​</a></h3><p><strong>原文</strong>：人神经元终末分化、长寿命，对基因剂量极为敏感（CNV 与杂合点突变关联多种神经发育与精神疾病）。作者对胎儿到出生后的人脑做了 2,357 个单神经元全基因组测序，发现产前皮层神经元平均 25.9%（12.7%–46%）携带高度异常的基因组——即涉及多条染色体的广泛 CNV；而出生后这一比例下降约 4.5 倍。携带广泛 CNV 的神经元主要在围产期被淘汰，时间大致与程序性细胞死亡期平行。</p><p><strong>深度扩展</strong>：</p><p>人神经元<strong>终末分化、长寿命</strong>，对基因剂量极为敏感——拷贝数变异（CNV）与杂合点突变被关联到多种神经发育与精神疾病。这项发表于《Nature》（2026 年 10 月 28 日）的工作，由 Diane D. Shao、Yifan Zhao、Joseph Brew、Yahia Adla、Urmi Ghosh、Vinayak V. Viswanadham 等完成，把「大脑基因组质量」这个长期模糊的问题变成了可量化的动态过程。</p><p>方法：对<strong>胎儿到出生后的人脑做了 2,357 个单神经元全基因组测序</strong>（两种 scWGS 方法）。关键数字：<strong>产前皮层神经元平均 25.9%（范围 12.7%–46%）携带高度异常的基因组</strong>——即涉及<strong>多条染色体</strong>的<strong>广泛 CNV</strong>；而<strong>出生后该比例下降约 4.5 倍</strong>（Fisher 合并 P = 3.5×10⁻⁶），说明携带广泛 CNV 的神经元主要在<strong>围产期被淘汰</strong>，时间大致<strong>与程序性细胞死亡期平行</strong>。</p><p>机制线索：对 <strong>44,861 个核</strong>的 snATAC/snRNA 分析显示，<strong>高 CNV 负荷神经元的突触基因表达异常</strong>；存活神经元的 CNV <strong>显著缺失剂量敏感基因与神经发育障碍相关基因</strong>（超几何检验 P&lt;0.05），提示存在<strong>选择性淘汰</strong>——异常的突触基因调控很可能是这些神经元被清除的诱因。为什么重要：<strong>正常大脑的「基因组质量」是在出生前后被主动筛选、而非天生如此</strong>，这为理解神经发育疾病的早期干预窗口提供了新框架。</p><p><strong>跨主题关联</strong>：与 <code>topics/neuroscience/index.md</code>、<code>topics/biomedicine/index.md</code> 的神经发育条目关联；「主动淘汰不合格单元以保系统稳定」与 <code>topics/ai-brain/index.md</code> 中知识网络的「清洗/去噪」逻辑同构。</p><hr><h2 id="🤖-二、ai-前沿" tabindex="-1">🤖 二、AI 前沿 <a class="header-anchor" href="#🤖-二、ai-前沿" aria-label="Permalink to &quot;🤖 二、AI 前沿&quot;">​</a></h2><h3 id="_6-thinkworld-把「动作思维」写成动力学链-再用世界想象做强化" tabindex="-1">6. ThinkWorld：把「动作思维」写成动力学链，再用世界想象做强化 <a class="header-anchor" href="#_6-thinkworld-把「动作思维」写成动力学链-再用世界想象做强化" aria-label="Permalink to &quot;6. ThinkWorld：把「动作思维」写成动力学链，再用世界想象做强化&quot;">​</a></h3><p><strong>原文</strong>：视觉-语言-动作（VLA）模型在机器人操作上进步快，但泛化受限于带动作标注的机器人演示的多样性与覆盖度；人类视频行为与环境经验更广，从中学习却面临「可扩展数据 vs 显式动作接地」的根本权衡。ThinkWorld 把动作推理扎根于世界动力学，并用世界想象 + 强化学习加以强化：它把每个动作思维表示为动力学链（Chain-of-Dynamics, CoD）——一串离散运动 token，刻画连接「当前世界」与「未来状态」的中间动力学，并作为跨本体的共同动作表示。</p><p><strong>深度扩展</strong>：</p><p>视觉-语言-动作（VLA）模型在机器人操作上进步很快，但泛化受限于<strong>带动作标注的机器人演示</strong>的多样性与覆盖度；人类视频行为与环境经验更广，从中学习却面临「<strong>可扩展数据 vs 显式动作接地</strong>」的根本权衡。这篇 arXiv 预印本（arXiv:2610.37666，2026-10-27；作者 Chaehyun Kim、Chi-Pin Huang、Jisoo Kim、Min-Hung Chen、Yu-Chiang Frank Wang、Seungryong Kim、Fu-En Yang）提出 <strong>ThinkWorld</strong>：把动作推理<strong>扎根于世界动力学</strong>，并用<strong>世界想象 + 强化学习</strong>强化。</p><p>方法：把每个动作思维表示为<strong>动力学链（Chain-of-Dynamics, CoD）</strong>——一串<strong>离散运动 token</strong>，刻画连接「当前世界」与「未来状态」的<strong>中间动力学</strong>，并作为<strong>跨本体的共同动作表示</strong>。训练流程：先用带动作标注的演示<strong>初始化</strong> CoD，再<strong>预测每个 CoD 诱导的未来</strong>、<strong>强化那些预测更贴合观测结果</strong>的 CoD。这样，<strong>无动作标注的视频</strong>也能通过观测到的<strong>状态转移</strong>提供直接监督，让人与机器人经验在<strong>同一推理空间</strong>互相精炼。关键卖点：仿真与真机实验显示有效的<strong>人→机迁移</strong>，以及对未见任务与环境的<strong>强泛化</strong>。为什么重要：它把「离散动作 token」升级为「动力学链」，用<strong>可验证的世界预测</strong>替代稀缺的动作标签——为大规模从视频中学习机器人策略提供了更可扩展的接口。</p><p><strong>跨主题关联</strong>：与 <code>topics/ai-system-architecture/index.md</code>、<code>topics/vibe-coding/index.md</code> 的 agent/世界模型条目关联；「用可验证的中间量做监督」与 <code>topics/ai-brain/index.md</code> 的「关联即可用」理念同构。</p><hr><h3 id="_7-把注意力看作格点规范场论-关系只能通过-wilson-环相互作用" tabindex="-1">7. 把注意力看作格点规范场论：关系只能通过 Wilson 环相互作用 <a class="header-anchor" href="#_7-把注意力看作格点规范场论-关系只能通过-wilson-环相互作用" aria-label="Permalink to &quot;7. 把注意力看作格点规范场论：关系只能通过 Wilson 环相互作用&quot;">​</a></h3><p><strong>原文</strong>：关系通过共享实体复合，顺序重要，验证一个复合关系等价于闭合一个回路。作者证明：若每个实体的坐标框架可独立旋转（逐实体规范自由），则三件事必然成立——① 在纯规范区，不共享任何环的关系根本无法相互作用；② 三角形的唯一规范不变分数是其和乐（holonomy）H = T_ij T_jk T_ki 的类函数，即一个 Wilson 环；③ 边的唯一等变更新形式是 U = Ψ(H)·T_ij。于是「用 Wilson 环做边注意力」不是众多设计之一，而是对称性唯一允许的形式。</p><p><strong>深度扩展</strong>：</p><p>关系通过共享实体复合（Alice 是 Bob 的母亲、Bob 是 Carol 的父亲 ⟹ Alice 是 Carol 的祖母），<strong>顺序重要</strong>（父亲的母亲 ≠ 母亲的父亲），而验证一个复合关系等价于<strong>闭合一个回路</strong>。这篇 arXiv 预印本（arXiv:2610.37656，2026-10-27；作者 Aakash Sarkar、Ananya Mukherjee、Motoshige Sato）证明了一个漂亮的<strong>唯一性定理</strong>：若每个实体的<strong>坐标框架可独立旋转</strong>（逐实体规范自由），则必然有三件事——① 在纯规范区，<strong>不共享任何环的关系根本无法相互作用</strong>；② 三角形的唯一规范不变分数是其<strong>和乐（holonomy）H = T_ij T_jk T_ki</strong> 的<strong>类函数</strong>，即一个 <strong>Wilson 环</strong>；③ 边的唯一等变更新形式是 <strong>U = Ψ(H)·T_ij</strong>（Ψ 共轭等变）。结论：「<strong>用 Wilson 环做边注意力</strong>」<strong>不是众多设计之一，而是对称性唯一允许的形式</strong>。</p><p>关键数字（零训练、仅靠复合）：在 <strong>1/5 边被污染的稀疏图</strong>上，以 <strong>0.88</strong> 推断出未观测的 <strong>S₄ 关系</strong>（与专门的同步算法相当或略低），而<strong>所有交换架构被卡在 0.083</strong>；其和乐分数以 <strong>AUC 0.99</strong> 标记被污染的三角形（交换分数被第二条选择规则卡在 0.76），并能<strong>无标签聚类</strong>。为什么重要：它把三套各自为战的社群接上了同一根线——知识图谱的<strong>交换算子嵌入</strong>是它的阿贝尔区；<strong>AlphaFold 的三角更新</strong>与 <strong>Edge Transformer</strong> 只有它的<strong>形状</strong>（边经第三个顶点更新）而缺<strong>约束</strong>；<strong>格点 QCD</strong> 则在格上等变地构造它。</p><p><strong>跨主题关联</strong>：与 <code>topics/physics/index.md</code>、<code>topics/quantum-physics/index.md</code>（规范场/对称性）及 <code>topics/ai-system-architecture/index.md</code>（注意力结构）强关联；与 <code>topics/cross-domain-synthesis-2026-q3.md</code> 的「约束-涌现」高度同构——对称性 = 唯一性来源。</p><hr><h3 id="_8-工具使用智能体的缩放律-扩「工具-数据库多样性」比堆任务数更值" tabindex="-1">8. 工具使用智能体的缩放律：扩「工具/数据库多样性」比堆任务数更值 <a class="header-anchor" href="#_8-工具使用智能体的缩放律-扩「工具-数据库多样性」比堆任务数更值" aria-label="Permalink to &quot;8. 工具使用智能体的缩放律：扩「工具/数据库多样性」比堆任务数更值&quot;">​</a></h3><p><strong>原文</strong>：要训出能完成复杂多步任务的大模型工具使用智能体，关键问题之一是：合成生成环境里的数据组成如何影响训练效果。作者提出 SynthAPI 流水线，沿工具、任务、数据库三条轴显式控制所生成环境的多样性。在 849 个模型（四种规模）、458,752 个任务上系统扫过生成参数，推导出一条缩放律：可由合成环境的规模与组成预测下游工具使用智能体的泛化。</p><p><strong>深度扩展</strong>：</p><p>要训出能完成复杂多步任务的<strong>工具使用智能体</strong>，一个关键问题是：<strong>合成生成环境里的数据组成</strong>如何影响训练效果。这篇 arXiv 预印本（arXiv:2610.37648，2026-10-27；作者 Andrew Szot、Samira Abnar、Omar Attia、Abbas Kazerouni、Michael Kirchhof、Cheng-Yu Hsieh、Raviteja Vemulapalli、Alexander Toshev）提出了 <strong>SynthAPI 流水线</strong>。</p><p>方法：沿<strong>工具、任务、数据库三条轴</strong>，<strong>显式控制</strong>所生成环境的多样性。规模：在 <strong>849 个模型（四种规模）、458,752 个任务</strong>上系统扫过生成参数，从而推导出一条<strong>缩放律</strong>——可由<strong>合成环境的规模与组成预测</strong>下游工具使用智能体的泛化。三条经验结论：随数据预算增长，<strong>扩展「工具多样性」与「数据库多样性」比增加任务数更有效</strong>；而<strong>提高数据复杂度收益更大</strong>。验证：按这些结论缩放得到的智能体，在<strong>四个评测基准</strong>上超过用既往工作数据训练的模型。</p><p>为什么重要：过去 agent 训练数据的「配方」多靠经验试错，这篇把「<strong>数据组成 → 泛化</strong>」变成一条可预测、可外推的缩放律——把「造环境」当成一门可优化的工程，而非玄学。它也与「数据质量/多样性 &gt; 数据量」的通用趋势一致。</p><p><strong>跨主题关联</strong>：与 <code>topics/ai-system-architecture/index.md</code>、<code>topics/ai-tools/index.md</code> 的工具使用/agent 笔记关联；「多样性是可预测的缩放变量」与 <code>topics/ai-brain/index.md</code> 的「关联越多、复利越强」同构。</p><hr><h3 id="_9-heads-of-security-用「可学习注意力门」做指令—数据分离-抗提示注入" tabindex="-1">9. Heads of Security：用「可学习注意力门」做指令—数据分离，抗提示注入 <a class="header-anchor" href="#_9-heads-of-security-用「可学习注意力门」做指令—数据分离-抗提示注入" aria-label="Permalink to &quot;9. Heads of Security：用「可学习注意力门」做指令—数据分离，抗提示注入&quot;">​</a></h3><p><strong>原文</strong>：HoS 是一种提示注入防御，用少量可学习的「逐头注意力门」来强制指令—数据分离：它学习每个注意力头应如何在「可信 token」与「不可信 token」之间重新分配注意力，让模型能推理不可信内容而不执行其中的注入指令。作者在 Llama-3.3-70B-Instruct 与 GPT-OSS-20B 上评测，并与基于微调的 SecAlign++、以及同样把指令—数据分离做进架构的 ASIDE 对比。</p><p><strong>深度扩展</strong>：</p><p><strong>HoS（Heads of Security）</strong> 是一种提示注入（prompt injection）防御，用<strong>少量可学习的「逐头注意力门」（per-head attention gates）</strong> 强制<strong>指令—数据分离</strong>：它学习<strong>每个注意力头应如何在「可信 token」与「不可信 token」之间重新分配注意力</strong>，让模型能<strong>推理</strong>不可信内容而<strong>不执行</strong>其中的注入指令。这篇 arXiv 预印本（arXiv:2610.37657，2026-10-27；作者 Igor Shilov、Xiaoxue Yang、Alexander Panfilov、Evgenii Kortukov、Matthieu Meeus、Peter Romov、Wojciech Samek、Jonas Geiping、Yves-Alexandre de Montjoye）在 <strong>Llama-3.3-70B-Instruct 与 GPT-OSS-20B</strong> 上评测，对比基于微调的 <strong>SecAlign++</strong>、以及同样把指令—数据分离做进架构的 <strong>ASIDE</strong>。</p><p>关键数字：黑盒 <strong>RL-Hammer</strong> 攻击对 GPT-OSS-20B 的 <strong>ASR（攻击成功率）达 97%</strong>、对 SecAlign <strong>85%</strong>，而<strong>对 HoS 只有 10%</strong>；白盒 <strong>Claudini</strong> 经 autoresearch 强化后，要让 HoS 达到同样 ASR 需<strong>多 3 倍 FLOPs</strong>。此外，HoS 在 <strong>few-shot</strong> 设置下仍保持基座效用（SecAlign/ASIDE 会退化）；在带静态攻击的智能体基准上 HoS 与 SecAlign 相近，而 ASIDE 因工具使用差只到 <strong>10% 效用</strong>。为什么重要：<strong>提示注入的稳健性可以通过「有针对性的注意力干预」获得，而不必牺牲通用能力</strong>——用极小的架构改动（门控），换取对自适应攻击的实质防护。</p><p><strong>跨主题关联</strong>：与 <code>topics/cybersecurity/index.md</code>、<code>topics/ai-system-architecture/index.md</code> 的 AI 安全/防御条目强关联；「分离可信与不可信信道」与 <code>topics/cross-domain-synthesis-2026-q3.md</code> 的「代码-状态分离」同构。</p><hr><h3 id="_10-无标签-rlvr-为何崩塌-跨任务耦合驱动的「集体不稳定性」" tabindex="-1">10. 无标签 RLVR 为何崩塌：跨任务耦合驱动的「集体不稳定性」 <a class="header-anchor" href="#_10-无标签-rlvr-为何崩塌-跨任务耦合驱动的「集体不稳定性」" aria-label="Permalink to &quot;10. 无标签 RLVR 为何崩塌：跨任务耦合驱动的「集体不稳定性」&quot;">​</a></h3><p><strong>原文</strong>：用可验证奖励做无标签强化学习（RLVR）时，奖励模型「与自己多数投票一致」：起初提升推理，但最终崩塌——自评奖励升到 1，而准确率下降，甚至对所有问题给出同一个答案。且这种崩塌只在训练使用很多问题时出现。作者把这种「依赖数据集规模」解释为一种集体不稳定性：在问题共享参数的可解多问题模型中，只要单问题自强化漂移 F 的群体平均斜率 ⟨F&#39;⟩ 为正，群体就会放大任何共享扰动。</p><p><strong>深度扩展</strong>：</p><p>用<strong>可验证奖励</strong>做<strong>无标签</strong>强化学习（RLVR）时，奖励模型「与自己多数投票一致」：起初提升推理，但<strong>最终崩塌</strong>——<strong>自评奖励升到 1，而准确率下降</strong>，甚至对所有问题给出<strong>同一个答案</strong>；且这种崩塌<strong>只在训练使用很多问题时出现</strong>。这篇 arXiv 预印本（arXiv:2610.37553，2026-10-27；作者 Peize Ding）把它解释为一种<strong>集体不稳定性</strong>。</p><p>机制：在问题<strong>共享参数</strong>的可解多问题模型中，只要单问题自强化漂移 F 的<strong>群体平均斜率 ⟨F&#39;⟩ 为正</strong>，群体就会<strong>放大任何共享扰动</strong>。核心是两种速度的竞赛——<strong>单问题锐化被 1/N 拖慢</strong>，而<strong>共享模以 ∝λ² 增长、与 N 无关</strong>（λ 为共享耦合强度）——由此出现<strong>临界问题数 N_c ≈ ln(1/δ)/(λ²G)</strong>。模拟验证了该预测：尖锐的相变、<strong>N_c ∝ λ⁻²</strong>（至多对数修正）、跨耦合/置信剖面/训练变体的<strong>单一临界放大 λ²NG</strong>、对批大小的<strong>对数依赖</strong>、以及<strong>初始模型自信时不崩塌</strong>。</p><p>实验（小 Transformer 无标签 RL）：<strong>去掉共享方向完全避免崩塌</strong>，恢复它则崩塌重现，且崩塌随训练集规模与基座模型熵增长。为什么重要：<strong>「自己给自己打分」的系统会因任务间耦合而集体塌陷</strong>——这是一个可以识别、可以拆解的动力学问题，而非单纯的训练 bug。</p><p><strong>跨主题关联</strong>：与 <code>topics/ai-system-architecture/index.md</code>、<code>topics/intelligence-self-learning/index.md</code> 的自学习/奖励崩塌条目关联；「反馈回路里的正反馈导致系统塌陷」与 <code>topics/cross-domain-synthesis-2026-q3.md</code> 的「约束-涌现 / 不可逆跃迁」同构。</p><hr><h2 id="🧠-机制层" tabindex="-1">🧠 机制层 <a class="header-anchor" href="#🧠-机制层" aria-label="Permalink to &quot;🧠 机制层&quot;">​</a></h2><h3 id="机制一-mct1-ldhb-的「线粒体内乳酸脱氢」——糖代谢的第二入口" tabindex="-1">机制一：MCT1/LDHB 的「线粒体内乳酸脱氢」——糖代谢的第二入口 <a class="header-anchor" href="#机制一-mct1-ldhb-的「线粒体内乳酸脱氢」——糖代谢的第二入口" aria-label="Permalink to &quot;机制一：MCT1/LDHB 的「线粒体内乳酸脱氢」——糖代谢的第二入口&quot;">​</a></h3><p>完整因果链要从<strong>糖代谢的教科书瓶颈</strong>说起：葡萄糖 →（胞质糖酵解）→ <strong>丙酮酸 + NADH</strong>。传统路径是丙酮酸经**线粒体丙酮酸载体（MPC）**穿过内膜进入基质 → 丙酮酸脱氢酶（PDH）→ 乙酰辅酶A → 三羧酸（TCA）循环 → 生成 NADH/FADH₂ → 交电子传递链（ETC）→ 氧化磷酸化产 ATP。这条链把 MPC 设成「唯一的门」，于是任何绕过它的碳流都被当作不存在。</p><p>本研究揭示的平行链：<strong>乳酸（来自胞质或循环）→ 经线粒体内膜上的 MCT1（Slc16a1）直接进入基质 → 与基质中的 LDHB 结合 → 乳酸 + NAD⁺ ⇌ 丙酮酸 + NADH（可逆反应，此处取耗乳酸方向）→ 生成的 NADH 直供复合体 I、丙酮酸进入 TCA</strong>。分子层面的关键在 <strong>LDH 同工酶的亚细胞定位</strong>：LDHA 偏好「丙酮酸→乳酸」（产乳酸），LDHB 偏好「乳酸→丙酮酸」（耗乳酸）。把偏好耗乳酸的 <strong>LDHB 放进线粒体基质</strong>、再配一个能运乳酸的 <strong>MCT1 于线粒体内膜</strong>，就等于在 TCA 循环门口开了一道「<strong>乳酸专线</strong>」。</p><p>证据链（自下而上）：① <strong>敲除 MPC</strong> 后小鼠心肌仍能氧化葡萄糖来源的碳 → 存在 bypass；② 该氧化<strong>依赖 MCT1</strong>（敲除即丧失）；③ 分级/定位实验显示 MCT1 存在于<strong>线粒体内膜</strong>（非仅质膜）；④ MCT1 与 <strong>LDHB</strong> 相互作用、共定位；⑤ 缺失 MCT1 → 乳酸氧化受损 → <strong>代谢灵活性下降</strong> → 在<strong>神经内分泌轴过度激活或缺血—再灌注</strong>后<strong>心衰加速、死亡率上升</strong>。</p><p>为什么重要：它把「<strong>代谢灵活性</strong>」这个抽象概念落到一个具体分子开关上。应激（如心衰时循环乳酸升高）下，乳酸其实是心肌的<strong>优选燃料</strong>；若这条线粒体乳酸入口缺失，心肌就无法把升高的乳酸转成能量，反而累积酸负荷。它也解释了一个悖论：为何某些心衰患者「葡萄糖利用看似正常却能量不足」——瓶颈不在丙酮酸，而在<strong>被忽视的乳酸入线粒体通路</strong>。</p><p><strong>可证伪预测</strong>：若在线粒体特异地把 MCT1 过表达/重新定位，应提升缺血—再灌注后的 ATP 产量与收缩恢复率；反之，线粒体特异 MCT1 敲低应再现「MPC 正常、代谢却不灵活」的表型。</p><hr><h3 id="机制二-围产期「基因组质检」——异常神经元为何在出生前后被清除" tabindex="-1">机制二：围产期「基因组质检」——异常神经元为何在出生前后被清除 <a class="header-anchor" href="#机制二-围产期「基因组质检」——异常神经元为何在出生前后被清除" aria-label="Permalink to &quot;机制二：围产期「基因组质检」——异常神经元为何在出生前后被清除&quot;">​</a></h3><p>这条机制链的核心问题是：<strong>人脑如何在数十年寿命里，维持一群不再分裂、对基因剂量极敏感的神经元的基因组质量？</strong> 答案是「<strong>出生前后的一次大规模质检</strong>」。</p><p>因果链：① <strong>产前</strong>皮层神经元在快速增殖/迁移中积累大量染色体错误——测序显示平均 <strong>25.9%（12.7%–46%）</strong> 携带涉及<strong>多条染色体</strong>的<strong>广泛 CNV</strong>（这是惊人的高比例，反映发育期有丝分裂的高错误率）；② 这些异常神经元在<strong>围产期被清退</strong>——出生后比例下降约 <strong>4.5 倍</strong>（Fisher 合并 P = 3.5×10⁻⁶），时间与<strong>程序性细胞死亡（PCD）期</strong>大致平行；③ <strong>选择是定向的</strong>：存活神经元的 CNV <strong>显著缺失剂量敏感基因与神经发育障碍相关基因</strong>（超几何检验 P&lt;0.05），说明不是随机丢失，而是<strong>按基因功能做取舍</strong>；④ 分子层面的「被判死刑」信号来自<strong>突触基因表达异常</strong>——44,861 个核的 snATAC/snRNA 显示高 CNV 负荷神经元的突触基因调控失调，异常的突触功能很可能是触发清除的诱因。</p><p>为什么这条机制范式重要：它把「<strong>突变负荷 → 功能缺陷 → 被清除</strong>」串成完整因果链，且清除发生在<strong>一个特定的发育窗口</strong>。这带来两个推论：其一，「正常大脑」的基因组并非天生干净，而是<strong>主动筛选</strong>的结果——大脑愿意用「淘汰约 1/4 产前神经元」换取成年后更高质量的神经元池；其二，这个窗口若被扰乱（如清除机制受损），存活下来的高 CNV 神经元可能是<strong>神经发育与精神疾病</strong>的细胞源头。</p><p><strong>可证伪预测</strong>：若人为削弱围产期 PCD 通路，应观察到出生后皮层高 CNV 神经元比例上升、并伴随突触/行为异常；若能增强对高 CNV 神经元的清除，则应在某些神经发育模型中出现症状缓解。</p><hr><h3 id="机制三-无标签-rlvr-的临界崩塌——「自评」系统的集体不稳定性" tabindex="-1">机制三：无标签 RLVR 的临界崩塌——「自评」系统的集体不稳定性 <a class="header-anchor" href="#机制三-无标签-rlvr-的临界崩塌——「自评」系统的集体不稳定性" aria-label="Permalink to &quot;机制三：无标签 RLVR 的临界崩塌——「自评」系统的集体不稳定性&quot;">​</a></h3><p>这条机制回答一个反常现象：为什么用<strong>可验证奖励</strong>做<strong>无标签</strong> RL（RLVR）时，系统会「<strong>自评奖励升到 1，准确率却下降</strong>，甚至对<strong>所有问题给同一答案</strong>」，且<strong>只在训练用很多问题时</strong>崩塌？</p><p>建模：设有一组<strong>共享参数</strong>的可解多问题模型，每个问题有自己的自强化漂移函数 F。<strong>单问题</strong>层面，若 F 的斜率使该问题「锐化」（向自信解收敛），单独训练是良性的。但当 N 个问题共享参数时，任何<strong>共享扰动</strong>会被放大——这是关键。作者导出一条<strong>临界条件</strong>：只要单问题自强化漂移 F 的<strong>群体平均斜率 ⟨F&#39;⟩ &gt; 0</strong>，群体就会<strong>放大任何共享扰动</strong>。</p><p><strong>两种速度的竞赛</strong>是核心直觉：<strong>单问题锐化被 1/N 拖慢</strong>（N 越大，每个问题单独暴露越少），而<strong>共享模以 ∝λ² 增长、与 N 无关</strong>（λ 为任务间共享耦合强度）。于是存在一个<strong>临界问题数 N_c ≈ ln(1/δ)/(λ²G)</strong>——问题数一旦超过 N_c，共享模的增长压倒单问题锐化，系统奔向一个「所有问题答案坍缩为一致」的集体模。</p><p>模拟验证：尖锐的相变、<strong>N_c ∝ λ⁻²</strong>（至多对数修正）、跨耦合/置信剖面/训练变体的<strong>单一临界放大 λ²NG</strong>、对批大小的<strong>对数依赖</strong>、以及<strong>初始模型自信时不崩塌</strong>（δ 小 → N_c 大）。在小 Transformer 的无标签 RL 实验中，<strong>去掉共享方向完全避免崩塌</strong>，恢复它则崩塌重现，且崩塌随训练集规模与基座模型熵增长——理论与实验闭环。</p><p>为什么重要：它把「自己给自己打分」的失败从「<strong>训练 bug</strong>」重述为「<strong>可识别、可拆解的动力学问题</strong>」——可以通过<strong>切断任务间共享耦合</strong>或<strong>控制问题数/批大小</strong>来规避，而非只能靠调参撞运气。</p><hr><h2 id="⚛️-第一性原理层" tabindex="-1">⚛️ 第一性原理层 <a class="header-anchor" href="#⚛️-第一性原理层" aria-label="Permalink to &quot;⚛️ 第一性原理层&quot;">​</a></h2><h3 id="原理一-对称性即唯一性——「wilson-环不是设计-而是必然」" tabindex="-1">原理一：对称性即唯一性——「Wilson 环不是设计，而是必然」 <a class="header-anchor" href="#原理一-对称性即唯一性——「wilson-环不是设计-而是必然」" aria-label="Permalink to &quot;原理一：对称性即唯一性——「Wilson 环不是设计，而是必然」&quot;">​</a></h3><p>本期条目 7 给出了一个近乎「物理定律」级的命题：<strong>一旦你承认每个实体的坐标框架可独立旋转（逐实体规范自由），那么「用 Wilson 环做边注意力」就不是众多可选设计之一，而是对称性唯一允许的形式</strong>。这与物理学的一条深层直觉同源：<strong>规范不变性（gauge invariance）极大压缩了可能理论的空间</strong>——电磁学的麦克斯韦方程组、杨-米尔斯的非阿贝尔场论，都是「规范对称 + 最小耦合」逼出来的，而非拍脑袋发明。数学上，这就是「<strong>约束即生成</strong>」：越强的对称要求，留下的自由度越少，唯一性越强。</p><p>把这个法则推到极处，会得到一个反直觉的结论：<strong>给关系建模时，「不共享任何环的关系无法相互作用」不是工程近似，而是纯规范区的定理</strong>。它在知识图谱里等价于一句朴素的洞察——<strong>孤立的、不成环的三元组之间没有可传播的信息</strong>；只有闭合回路（Wilson 环 / holonomy）才能承载规范不变的「关系强度」。反观 AlphaFold 的三角更新与 Edge Transformer：它们有<strong>形状</strong>（边经由第三个顶点更新）却缺<strong>约束</strong>——即测了和乐却没有把它做成唯一合法的等变形式。</p><p><strong>可证伪预测</strong>：若该定理成立，任何「非 Wilson 环形式、却声称等价或更优」的边注意力，在<strong>真正需要顺序敏感复合</strong>（如非交换关系、S₄ 群）的任务上必然劣于 holonomy attention，或需要额外对称破缺假设才能追平。这给「注意力架构设计」设了一条<strong>可检验的下界</strong>。</p><hr><h3 id="原理二-非绝热跃迁——一切「被迫跨临界点」的系统都有同一套动力学" tabindex="-1">原理二：非绝热跃迁——一切「被迫跨临界点」的系统都有同一套动力学 <a class="header-anchor" href="#原理二-非绝热跃迁——一切「被迫跨临界点」的系统都有同一套动力学" aria-label="Permalink to &quot;原理二：非绝热跃迁——一切「被迫跨临界点」的系统都有同一套动力学&quot;">​</a></h3><p>本期至少有<strong>三</strong>条互相独立的现象，被同一个第一性原理串起来：<strong>当参数被迫快速扫过临界点、系统来不及绝热跟随，就会发生相干跃迁或集体坍缩</strong>。</p><p>其一，条目 2 的<strong>非绝热 Landau–Zener–Majorana 隧穿</strong>：强光场在阿秒尺度加速电子，扫过能带简并点太快，电子来不及留在本征态，于是发生<strong>带间隧穿</strong>——概率由 Landau–Zener 公式 P = exp(−2πΔ²/(ℏ|dε/dt|)) 决定，能隙 Δ 越小、扫速越快，隧穿概率越高。其二，条目 10 的<strong>无标签 RLVR 崩塌</strong>：训练作为一次「问题数扫过临界值 N_c」的过程，一旦 N &gt; N_c，系统<strong>来不及在各任务上独立锐化</strong>，共享模反而放大扰动，答案集体坍缩——这正是一次<strong>宏观尺度的非绝热相变</strong>。其三，条目 5 的<strong>围产期神经元清除</strong>：发育时钟扫过程序性死亡窗口，基因组异常的神经元「来不及修复」即被淘汰。</p><p>统一逻辑：<strong>快扫（|dλ/dt| 大）+ 小能隙/弱约束 = 跃迁/坍缩</strong>；<strong>慢扫 + 大能隙 = 绝热跟随、结构保留</strong>。这是一个<strong>跨越量子物理、机器学习动力学与发育生物学</strong>的同构——「不可逆跃迁」是 <code>topics/cross-domain-synthesis-2026-q3.md</code> 的五大跨领域模式之一，本期的三条现象恰好是它在三个尺度上的实现。</p><p><strong>可证伪预测</strong>：在任何 RLVR 系统中，<strong>降低问题间的共享耦合 λ</strong> 或 <strong>降低问题数 N</strong> 应把系统推回绝热区、避免崩塌；这与 N_c ∝ λ⁻² 的标度一致，可直接实验检验。</p><hr><h2 id="🔗-交叉关联" tabindex="-1">🔗 交叉关联 <a class="header-anchor" href="#🔗-交叉关联" aria-label="Permalink to &quot;🔗 交叉关联&quot;">​</a></h2><p>本期 10 条共享一条<strong>统一逻辑：「约束/对称性决定系统的可能性空间」</strong>。</p><ul><li><strong>材料与量子（1、2、7）</strong>：碳戊搭烯的本征金属性来自<strong>拓扑约束</strong>（五元/七元环的非苯环拼接改变了态密度与能隙）；LZM 隧穿来自<strong>时间依赖哈密顿量的对称约束</strong>；Wilson 环来自<strong>规范对称的唯一化</strong>。三者都在说：<strong>不是「加了什么」决定行为，而是「被什么约束」决定行为</strong>。</li><li><strong>生命与演化（4、5）</strong>：MCT1 乳酸通道是<strong>冗余通路</strong>——约束被单点移除（敲除 MPC）时系统靠备用通路的鲁棒性存活；围产期神经元清除则是<strong>主动施加约束</strong>（淘汰 1/4 产前神经元）以换取长期基因组质量。鲁棒性与质量，都源于对「非必要自由度」的取舍。</li><li><strong>AI（6、8、9、10）</strong>：ThinkWorld 用<strong>世界动力学约束</strong>动作表示；SynthAPI 证明<strong>多样性是缩放变量</strong>（约束数据组成即可预测泛化）；HoS 用<strong>注意力门约束</strong>指令—数据边界；RLVR 崩塌则是<strong>约束缺失</strong>（没有外部真值、只靠自评）导致的集体失控。AI 的四条恰好构成「<strong>约束保结构、失约束则塌陷</strong>」的正反面。</li></ul><p><strong>与库内主题的深层同构</strong>：这一逻辑与 <code>topics/cross-domain-synthesis-2026-q3.md</code> 的核心模式「<strong>约束-涌现</strong>」完全重合——黏液屏障、神经元清除、MCT1 冗余、RLVR 崩塌、Wilson 环，都是「<strong>约束维护结构，消除约束 = 崩溃</strong>」在不同领域的实例。它也与 <code>topics/ai-brain/index.md</code> 的自洽逻辑呼应：知识网络之所以产生复利，正是因为<strong>每条新信息都被约束（关联）进既有结构</strong>，而非孤立堆放——无约束的信息，就像无 Wilson 环的关系，无法相互作用。</p><hr><p>关键词：碳戊搭烯, carbon pentaheptite, CPHN, 非苯环, 表面合成, on-surface synthesis, 本征金属, 电导量子, 10.1038/s41586-026-11202-2, Nature 2026, Jianmin Huang, Qitang Fan；Landau-Zener-Majorana, 子周期录像, subcycle videography, 石墨烯, 狄拉克能带, 阿秒, 10.1038/s41586-026-11214-y, V. Eggers, R. Wallauer；硅酮解聚, back-to-monomer, 脱氧氯化, 硅鎓离子, silylium, 二氯硅烷, 光气, 10.1038/s41586-026-11335-4, Stefan Grimme, Hendrik Klare, 波恩大学；MCT1, Slc16a1, LDHB, 乳酸, 线粒体丙酮酸载体, MPC, 心肌代谢, 10.1038/s41586-026-11182-3, Ahmad Cluntun；围产期神经元清除, CNV, 单神经元全基因组测序, scWGS, 突触基因, 10.1038/s41586-026-11190-3, Diane Shao；ThinkWorld, Chain-of-Dynamics, VLA, 世界模型, arXiv:2610.37666；Attention as Lattice Gauge Theory, Wilson loop, holonomy, 规范场论, arXiv:2610.37656, Aakash Sarkar；SynthAPI, 工具使用智能体, 缩放律, 环境合成, arXiv:2610.37648, Andrew Szot, Google；Heads of Security, 提示注入, attention gate, prompt injection, arXiv:2610.37657, Jonas Geiping；无标签 RLVR, policy collapse, 集体不稳定性, 临界问题数, arXiv:2610.37553, Peize Ding</p><p>关联：topics/materials/index.md, topics/physics/index.md, topics/quantum-physics/index.md, topics/biomedicine/index.md, topics/neuroscience/index.md, topics/ai-system-architecture/index.md, topics/ai-tools/index.md, topics/intelligence-self-learning/index.md, topics/cybersecurity/index.md, topics/vibe-coding/index.md, topics/science-news/index.md, topics/ai-brain/index.md, topics/cross-domain-synthesis-2026-q3.md</p>',118)])])}const m=n(g,[["render",e]]);export{h as __pageData,m as default};
